using System.IO.Compression;
using Vni.Ielts.Application.Importing;
using Vni.Ielts.Domain.Exams;
using Vni.Ielts.Infrastructure.Content.Import;
using static Vni.Ielts.Infrastructure.Tests.Content.Import.HostileArchives;

namespace Vni.Ielts.Infrastructure.Tests.Content.Import;

/// <summary>
/// docs/security/zip-ingestion-security.md § Testing, made real. Every
/// fixture is generated by <see cref="HostileArchives"/>; the limits are
/// passed explicitly and kept tight so each archive stays a few kilobytes.
///
/// The three checks that matter most — ratio, path escape, streaming quota —
/// were each watched going red with the check removed before this file was
/// accepted. → the S6 report
/// </summary>
public sealed class ExamPackageArchiveInspectorTests : IDisposable
{
    private readonly string sandbox = Path.Combine(Path.GetTempPath(), $"vni-zip-{Guid.NewGuid():n}");
    private readonly ExamPackageArchiveInspector inspector = new();

    /// <summary>Tight on purpose: a 10 KB bomb and a 4 KB file are both over-sized against these.</summary>
    private static readonly ImportArchiveLimits Tight = new(
        MaxEntries: 8,
        MaxTotalUncompressedBytes: 4_096,
        MaxEntryUncompressedBytes: 2_048,
        MaxCompressionRatio: 20,
        MaxArchiveBytes: 64 * 1024,
        ExtractionTimeout: TimeSpan.FromSeconds(10));

    private static string Error => "error";
    private static string Warning => "warning";

    // ── Signature and archive-level caps ─────────────────────────────────

    [Fact]
    public async Task A_file_that_is_not_a_zip_is_refused_by_its_first_bytes()
    {
        var result = await inspector.InspectAsync(NotAZip(), Tight, default);

        AssertRefused(result, ArchiveFindingCodes.NotAnArchive);
    }

    [Fact]
    public async Task An_empty_archive_is_refused_as_empty_not_as_corrupt()
    {
        var result = await inspector.InspectAsync(Empty(), Tight, default);

        AssertRefused(result, ArchiveFindingCodes.LayoutEmpty);
    }

    [Fact]
    public async Task An_upload_over_the_archive_byte_cap_is_refused_before_the_directory_is_read()
    {
        var limits = Tight with { MaxArchiveBytes = 64 };

        var result = await inspector.InspectAsync(FullPackage(), limits, default);

        AssertRefused(result, ArchiveFindingCodes.TooLarge);
    }

    [Fact]
    public async Task An_unseekable_upload_over_the_cap_is_refused_while_being_spooled()
    {
        var limits = Tight with { MaxArchiveBytes = 64 };

        var result = await inspector.InspectAsync(Unseekable(FullPackage()), limits, default);

        AssertRefused(result, ArchiveFindingCodes.TooLarge);
    }

    [Fact]
    public async Task An_unseekable_valid_upload_is_spooled_and_inspected()
    {
        var result = await inspector.InspectAsync(Unseekable(FullPackage()), Tight, default);

        Assert.True(result.IsAcceptable, Describe(result));
        Assert.Equal(4, result.Layout.PresentSkills.Count);
    }

    [Fact]
    public async Task Too_many_entries_is_refused_at_the_cap_plus_one()
    {
        var atCap = Enumerable.Range(0, Tight.MaxEntries).Select(i => File($"reading/{i}.txt")).ToArray();
        var overCap = atCap.Append(File("reading/one-more.txt")).ToArray();

        var accepted = await inspector.InspectAsync(Build(atCap), Tight, default);
        var refused = await inspector.InspectAsync(Build(overCap), Tight, default);

        Assert.True(accepted.IsAcceptable, Describe(accepted));
        AssertRefused(refused, ArchiveFindingCodes.TooManyEntries);
    }

    [Fact]
    public async Task Declared_total_over_the_cap_is_refused_from_the_central_directory_alone()
    {
        // Three entries each under the per-entry cap, together over the total.
        var text = new string('a', 1_500);
        var archive = Build(
            File("reading/a.txt", text), File("reading/b.txt", text), File("reading/c.txt", text));

        var result = await inspector.InspectAsync(archive, Tight, default);

        AssertRefused(result, ArchiveFindingCodes.TotalSizeExceeded);
    }

    [Fact]
    public async Task A_single_entry_over_the_per_entry_cap_is_refused()
    {
        var archive = Build(File("reading/big.txt", new string('a', 3_000)));

        var result = await inspector.InspectAsync(archive, Tight, default);

        AssertRefused(result, ArchiveFindingCodes.EntryTooLarge);
    }

    // ── Bomb ─────────────────────────────────────────────────────────────

    [Fact]
    public async Task A_compression_bomb_is_refused_by_its_ratio()
    {
        // 1,500 zero bytes deflate to a few dozen: well past 20:1, and under
        // the per-entry cap so that the ratio is the only check that fires.
        var bomb = Build(Bytes("reading/bomb.txt", new byte[1_500], level: CompressionLevel.SmallestSize));

        var result = await inspector.InspectAsync(bomb, Tight, default);

        AssertRefused(result, ArchiveFindingCodes.CompressionRatio);
    }

    [Fact]
    public async Task Ordinary_text_is_not_mistaken_for_a_bomb()
    {
        var prose = string.Join(' ', Enumerable.Range(0, 150).Select(i => $"word{i % 37}"));

        var result = await inspector.InspectAsync(Build(File("reading/prose.txt", prose)), Tight, default);

        Assert.True(result.IsAcceptable, Describe(result));
    }

    // ── Paths ────────────────────────────────────────────────────────────

    [Fact]
    public async Task Dot_dot_traversal_is_refused_as_path_escape()
    {
        var result = await inspector.InspectAsync(Traversal(), Tight, default);

        AssertRefused(result, ArchiveFindingCodes.PathEscape, "../../evil.txt");
    }

    [Fact]
    public async Task Backslash_traversal_is_normalised_then_refused()
    {
        var result = await inspector.InspectAsync(BackslashTraversal(), Tight, default);

        AssertRefused(result, ArchiveFindingCodes.PathEscape);
    }

    [Theory]
    [InlineData("/etc/passwd")]
    [InlineData(@"C:\x.txt")]
    [InlineData("//server/share/x.txt")]
    public async Task Absolute_paths_are_refused(string name)
    {
        var result = await inspector.InspectAsync(Build(File(name)), Tight, default);

        AssertRefused(result, ArchiveFindingCodes.PathEscape);
    }

    [Fact]
    public async Task A_null_byte_in_a_name_is_refused()
    {
        var result = await inspector.InspectAsync(NullByte(), Tight, default);

        AssertRefused(result, ArchiveFindingCodes.PathInvalid);
        Assert.DoesNotContain('\0', result.Findings[0].Path);
