    [Theory]
    [InlineData("reading/CON.json")]
    [InlineData("reading/con")]
    [InlineData("reading/LPT1.txt")]
    [InlineData("reading/NUL/x.txt")]
    public async Task Reserved_device_names_are_refused_case_insensitively(string name)
