    [Fact]
    public async Task No_finding_message_reveals_a_numeric_limit()
    {
        var limits = Tight with { MaxEntries = 3, MaxCompressionRatio = 7, MaxEntryUncompressedBytes = 999, MaxTotalUncompressedBytes = 1_234, MaxArchiveBytes = 55_555 };
        var archives = new[]
        {
            Bomb(1_500),
            Build(File("reading/big.txt", new string('a', 1_100))),
            Build(Enumerable.Range(0, 4).Select(i => File($"reading/{i}.txt")).ToArray()),
        };

        foreach (var archive in archives)
        {
            var result = await inspector.InspectAsync(archive, limits, default);

            Assert.False(result.IsAcceptable);
            foreach (var finding in result.Findings)
            {
                foreach (var number in new[] { "3", "7", "999", "1234", "1,234", "55555" })
                    Assert.DoesNotContain(number, finding.Message, StringComparison.Ordinal);
            }
        }
    }

    // ── Extraction ───────────────────────────────────────────────────────

    [Fact]
    public async Task Extraction_places_accepted_files_only_under_a_fresh_directory_in_the_sandbox()
    {
        var archive = Build(File("reading/p1.txt", "passage"), File("speaking/q.txt", "cue"), File("stray.txt", "no"));
        var inspection = await inspector.InspectAsync(archive, Tight, default);

        var extraction = await inspector.ExtractToSandboxAsync(archive, inspection, sandbox, Tight, default);

        Assert.True(extraction.IsSuccess, Describe(extraction));
        var directory = extraction.SandboxDirectory!;
        Assert.StartsWith(Path.GetFullPath(sandbox) + Path.DirectorySeparatorChar, directory, StringComparison.OrdinalIgnoreCase);
        Assert.Equal("passage", await System.IO.File.ReadAllTextAsync(Path.Combine(directory, "reading", "p1.txt")));
        Assert.Equal("cue", await System.IO.File.ReadAllTextAsync(Path.Combine(directory, "speaking", "q.txt")));
        Assert.False(System.IO.File.Exists(Path.Combine(directory, "stray.txt")), "an unknown entry was extracted");
        Assert.Equal(2, extraction.FilesWritten);
        Assert.Equal("passage".Length + "cue".Length, extraction.BytesWritten);

        var everything = Directory.GetFiles(sandbox, "*", SearchOption.AllDirectories);
        Assert.Equal(2, everything.Length);
        Assert.All(everything, f => Assert.StartsWith(directory, f, StringComparison.OrdinalIgnoreCase));
    }

    [Fact]
    public async Task Two_extractions_of_the_same_package_never_share_a_directory()
    {
        var archive = FullPackage();
        var inspection = await inspector.InspectAsync(archive, Tight, default);

        var first = await inspector.ExtractToSandboxAsync(archive, inspection, sandbox, Tight, default);
        var second = await inspector.ExtractToSandboxAsync(archive, inspection, sandbox, Tight, default);

        Assert.True(first.IsSuccess && second.IsSuccess);
        Assert.NotEqual(first.SandboxDirectory, second.SandboxDirectory);
    }

    [Fact]
    public async Task Extraction_refuses_an_inspection_that_was_not_acceptable()
    {
        var archive = Traversal();
        var inspection = await inspector.InspectAsync(archive, Tight, default);

        await Assert.ThrowsAsync<InvalidOperationException>(
            () => inspector.ExtractToSandboxAsync(archive, inspection, sandbox, Tight, default));

        Assert.False(Directory.Exists(sandbox) && Directory.EnumerateFileSystemEntries(sandbox).Any());
    }

    [Fact]
    public async Task A_header_that_lies_about_its_size_is_caught_by_the_streaming_quota_and_the_sandbox_is_removed()
    {
        // Declared 100 bytes, delivers 3,000: inspection passes on the
        // declared figure, extraction counts the real one.
        var archive = LyingHeader("reading/liar.bin", realSize: 3_000, declaredSize: 100);
        var inspection = await inspector.InspectAsync(archive, Tight, default);
        Assert.True(inspection.IsAcceptable, Describe(inspection));

        var extraction = await inspector.ExtractToSandboxAsync(archive, inspection, sandbox, Tight, default);

        Assert.False(extraction.IsSuccess);
        Assert.Equal(ArchiveFindingCodes.ExtractionQuotaExceeded, Assert.Single(extraction.Findings).Code);
        Assert.Null(extraction.SandboxDirectory);
        AssertSandboxEmpty();
    }

    [Fact]
    public async Task A_header_that_lies_within_the_quota_is_still_refused()
    {
        var archive = LyingHeader("reading/liar.bin", realSize: 900, declaredSize: 100);
        var inspection = await inspector.InspectAsync(archive, Tight, default);

        var extraction = await inspector.ExtractToSandboxAsync(archive, inspection, sandbox, Tight, default);

        Assert.False(extraction.IsSuccess);
        Assert.Equal(ArchiveFindingCodes.EntrySizeMismatch, Assert.Single(extraction.Findings).Code);
        AssertSandboxEmpty();
    }

    [Fact]
    public async Task Extraction_re_checks_every_entry_against_the_archive_it_is_given()
    {
        // The inspection came from a clean archive; the stream handed to
        // extraction is hostile. The inspection is never trusted over the bytes.
        var clean = Build(File("reading/ok.txt"));
        var inspection = await inspector.InspectAsync(clean, Tight, default);

        var extraction = await inspector.ExtractToSandboxAsync(Traversal(), inspection, sandbox, Tight, default);

        Assert.False(extraction.IsSuccess);
        Assert.Equal(ArchiveFindingCodes.PathEscape, Assert.Single(extraction.Findings).Code);
        AssertSandboxEmpty();
    }

    [Fact]
    public async Task Extraction_times_out_and_removes_the_sandbox()
    {
        var archive = FullPackage();
        var inspection = await inspector.InspectAsync(archive, Tight, default);
        var limits = Tight with { ExtractionTimeout = TimeSpan.FromMilliseconds(5) };

        var extraction = await inspector.ExtractToSandboxAsync(
            Slow(archive, perRead: TimeSpan.FromMilliseconds(150)), inspection, sandbox, limits, default);

        Assert.False(extraction.IsSuccess);
        Assert.Equal(ArchiveFindingCodes.ExtractionTimeout, Assert.Single(extraction.Findings).Code);
        AssertSandboxEmpty();
    }

    [Fact]
    public async Task A_cancelled_caller_token_propagates_rather_than_becoming_a_verdict()
    {
        var archive = FullPackage();
        var inspection = await inspector.InspectAsync(archive, Tight, default);
        using var cancelled = new CancellationTokenSource();
        cancelled.Cancel();

        await Assert.ThrowsAnyAsync<OperationCanceledException>(
            () => inspector.ExtractToSandboxAsync(archive, inspection, sandbox, Tight, cancelled.Token));

        AssertSandboxEmpty();
    }

    // ── Options seam ─────────────────────────────────────────────────────

    [Fact]
    public void Options_defaults_are_sane_and_nonsense_is_reported_all_at_once()
    {
        Assert.Empty(new ImportArchiveOptions().Problems());

        var broken = new ImportArchiveOptions
        {
            MaxEntries = 0, MaxCompressionRatio = -1, ExtractionTimeoutSeconds = 0,
            MaxEntryUncompressedBytes = 10, MaxTotalUncompressedBytes = 5,
        };

        var problems = broken.Problems();

        Assert.Equal(4, problems.Count);
        Assert.All(problems, p => Assert.StartsWith("Import:Archive:", p, StringComparison.Ordinal));
    }

    // ── Helpers ──────────────────────────────────────────────────────────

    private static void AssertRefused(ArchiveInspection result, string code, string? path = null)
    {
        Assert.False(result.IsAcceptable, "expected a refusal but the archive was acceptable");
        var finding = Assert.Single(result.Findings, f => f.Code == code);
        Assert.Equal(Error, finding.Severity);
        if (path is not null) Assert.Equal(path, finding.Path);
    }

    private void AssertSandboxEmpty()
    {
        if (!Directory.Exists(sandbox)) return;
        Assert.Empty(Directory.EnumerateFileSystemEntries(sandbox));
    }

    private static string Describe(ArchiveInspection result) =>
        string.Join("; ", result.Findings.Select(f => $"{f.Severity} {f.Code} {f.Path}: {f.Message}"));

    private static string Describe(ArchiveExtraction result) =>
        string.Join("; ", result.Findings.Select(f => $"{f.Severity} {f.Code} {f.Path}: {f.Message}"));

    public void Dispose()
    {
        if (Directory.Exists(sandbox)) Directory.Delete(sandbox, recursive: true);
    }
}
